window.DECK = {"title": "Expertise and the productivity effects of AI", "date": "November 11, 2026", "duration": 110, "description": "Expertise and occupational wages; AI assistance in customer support; a randomized patent-lawyer experiment separating assisted drafting from unaided judgment.", "draft_date": "2026-10-25", "author": "Sergio Ocampo", "slides": [{"title": "Expertise and the productivity effects of AI", "html": "<p>AI assistance, the value of expertise &amp; learning on the job<\/p><p>Sergio Ocampo<br>ECON 3399 · AI and Robots at Work<\/p>", "notes": "", "minutes": 0.5, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "class": "cover", "id": "s01", "teaching_role": "setup", "revision": "patent-revision-2026-10-29"}, {"title": "Three papers on expertise, productivity and learning", "html": "<table class=\"results\"><thead><tr><th>Paper<\/th><th>Question<\/th><\/tr><\/thead><tbody><tr><td>Autor &amp; Thompson<br>Expertise<\/td><td>Which tasks make expertise valuable?<\/td><\/tr><tr><td>Brynjolfsson, Li &amp; Raymond<br>Generative AI at Work<\/td><td>Who becomes more productive with an assistant?<\/td><\/tr><tr><td>Autor et al.<br>Patent-lawyer experiment<\/td><td>Does AI-assisted work develop independent judgment?<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Expertise determines who can do the work.<br>AI can change both access to that expertise and how it is acquired.<\/div>", "notes": "", "minutes": 2.5, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s03", "revision": "patent-revision-2026-10-29", "teaching_role": "setup", "class": "expertise-overview"}, {"id": "paper-expertise", "title": "Expertise", "html": "<div class=\"paper-identity-layout\"><figure><img src=\"figures/paper_expertise.png\" alt=\"Published article · First page: Expertise\"><figcaption>Published article · First page<\/figcaption><\/figure><div class=\"paper-details\"><p>David Autor and Neil Thompson<\/p><p><strong>Journal of the European Economic Association · 2025<\/strong><\/p><p class=\"small\"><a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a><\/p><\/div><\/div>", "notes": "", "minutes": 0, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a> · Journal of the European Economic Association · 2025", "class": "paper-identity", "teaching_role": "paper_identity"}, {"id": "expertise-question", "title": "Automation changes the expertise needed in an occupation or job", "html": "<ul><li>Occupations are bundles of tasks<\/li><li>Tasks require <em>expertise<\/em> to be performed<\/li><li>Automation takes away tasks and changes expertise<\/li><\/ul><table class=\"results\"><caption>Accounting and inventory clerks after automation<\/caption><thead><tr><th>Occupation<\/th><th>Routine work automated<\/th><th>Work left with people<\/th><\/tr><\/thead><tbody><tr><td>Accounting clerks<\/td><td>Record transactions; reconcile records<\/td><td>Resolve discrepancies; exercise accounting judgment<\/td><\/tr><tr><td>Inventory clerks<\/td><td>Calculate prices; manage inventory records<\/td><td>Count, stock &amp; weigh goods<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Similar exposure can leave very different expertise requirements in the remaining job.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Introduction", "minutes": 3, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "expertise-setup expertise-motivation"}, {"title": "Expertise determines which tasks a worker can perform", "html": "<table class=\"results\"><colgroup><col style=\"width:29%\"><col style=\"width:71%\"><\/colgroup><thead><tr><th>Object<\/th><th>Meaning in the model<\/th><\/tr><\/thead><tbody><tr><td>Worker expertise \\(e\\)<\/td><td>A capability level between 0 and 1; worker e can do task t if e ≥ t.<\/td><\/tr><tr><td>Task requirement \\(t\\)<\/td><td>Expert tasks have t &gt; 0; generic tasks have t ≤ 0.<\/td><\/tr><tr><td>Occupation \\(\\varphi\\)<\/td><td>The highest task requirement in its bundle.<\/td><\/tr><tr><td>Automation frontier \\(I\\)<\/td><td>Capital can perform expert tasks with \\(0&lt;t\\le I\\).<\/td><\/tr><tr><td>Generic work \\(\\theta&gt;1\\)<\/td><td>Controls the amount of generic (<strong>human!<\/strong>) work.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">More expert occupations contain fewer generic tasks, but always some.<br>Automation changes who performs the tasks; it does not redraw these bundles.<\/div><figure><img src=\"figures/expertise_automation_bars.svg\" alt=\"Three stages for the same occupation: generic tasks remain human; automation moves from zero to I, and then to varphi, replacing all expert tasks.\"><\/figure>", "notes": "", "minutes": 2.5, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 2: model definitions", "id": "s04", "teaching_role": "setup", "revision": "consolidation-2026-10-29", "class": "expertise-task-timeline"}, {"id": "expertise-task-space", "title": "Each vertical slice is one occupation’s task bundle", "minutes": 3, "teaching_role": "setup", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figure 1, PDF p. 12", "html": "<figure><img src=\"figures/expertise_task_space.png\" alt=\"Figure 1: occupations on the horizontal axis; tasks on the vertical axis. Green generic tasks remain in both example occupations.\" style=\"max-height:355px\"><figcaption>Figure 1. I₀: automation frontier; tₗ/tₕ: lower/upper endpoints of a bundle.<br>Green: generic tasks; red: automated tasks; blue: still-expert tasks.<\/figcaption><\/figure><div class=\"takeaway\">Left occupation: capital performs every expert task; people do generic work.<br>Right occupation: its worker still performs both generic and expert tasks.<\/div>", "notes": "", "revision": "generic-tasks-2026-10-29"}, {"id": "expertise-bundle-example", "title": "Follow one occupation as automation advances", "html": "<p>Illustrative occupation: its most demanding task requires <strong>\\(\\varphi\\) = 0.6<\/strong>.<\/p><table class=\"results\"><colgroup><col style=\"width:17%\"><col style=\"width:49%\"><col style=\"width:34%\"><\/colgroup><thead><tr><th>Frontier<\/th><th>Human work left<\/th><th>Who can enter?<\/th><\/tr><\/thead><tbody><tr><td>I = 0.3<\/td><td>Expert tasks from 0.3 to 0.6 + generic tasks<\/td><td>Workers with e ≥ 0.6<\/td><\/tr><tr><td>I = 0.6<\/td><td>Generic tasks only<\/td><td>Workers at any expertise level<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\"><strong>Productivity:<\/strong> saving expert time can raise the expert wage.<br><strong>Entry:<\/strong> opening the job to everyone can eliminate the expert premium.<\/div>", "notes": "", "minutes": 4, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 2: productivity and entry · illustrative thresholds", "revision": "merged-example-and-wage-effects-2026-10-29", "teaching_role": "setup", "class": "expertise-centered-setup"}, {"id": "expertise-figure-setup", "title": "The next two figures solve a sequence of equilibria", "html": "<p>Move <strong>I<\/strong> to the right; hold the capital stock and worker skills fixed.<\/p><table class=\"results\"><colgroup><col style=\"width:35%\"><col style=\"width:65%\"><\/colgroup><thead><tr><th>Object in the figures<\/th><th>How to read it<\/th><\/tr><\/thead><tbody><tr><td>\\(w(\\varphi)\\): blue curves<\/td><td>Wage in an occupation still requiring expertise.<\/td><\/tr><tr><td>\\(w_g\\): green; \\(r\\): red<\/td><td>Generic wage; rental payment per unit of capital.<\/td><\/tr><tr><td>\\(L(\\varphi)\\): employment<\/td><td>Labour allocated to an occupation type; expert jobs start at 1.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Worker expertise \\(e\\) is distributed uniformly between 0 and 1.<br>Workers choose the highest-paying occupation they can perform.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figures 2–3, PDF pp. 19–20", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "expertise-centered-setup"}, {"id": "expertise-theory-wages", "title": "The model predicts gains and losses across expertise levels", "html": "<figure class=\"theory-figure\"><h2>Wages vs Automation<\/h2><img style=\"max-height:340px\" src=\"figures/expertise_theory_wages.png\" alt=\"Figure 2. Horizontal: automation frontier I. Vertical: wages and capital rental in model units. Blue: w(varphi); green: w_g; red: r.\"><figcaption>Figure 2. Horizontal: automation frontier I. Vertical: wages and capital rental in model units. Blue: w(\\(\\varphi\\)); green: w_g; red: r.<\/figcaption><\/figure><div class=\"takeaway\">Expertise benefits from labor saving automation, as long as \\(I&lt;\\varphi\\).<br>Full automation removes expertise premium \\(\\longrightarrow\\) Sudden collapse in wages<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figure 2, PDF p. 19", "minutes": 4.0, "revision": "definitions-2026-10-29", "teaching_role": "result_exhibit", "class": "expertise-wage-result"}, {"id": "expertise-theory-employment", "title": "Changing expertise requirements reallocates employment", "html": "<figure class=\"theory-figure\"><h2>Generic Employment vs Automation<\/h2><img style=\"max-height:340px\" src=\"figures/expertise_theory_employment.png\" alt=\"Figure 3. Horizontal: I. Vertical: employment density L(varphi), initially 1 for expert jobs. Blue: still-expert jobs; green: jobs whose expert tasks have been automated.\"><figcaption>Figure 3. Horizontal: I. Vertical: employment density L(\\(\\varphi\\)), initially 1 for expert jobs. Blue: still-expert jobs; green: jobs whose expert tasks have been automated.<\/figcaption><\/figure><div class=\"takeaway\">At I = \\(\\varphi\\), entry expands even as the occupational wage drops.<br>Later automation draws workers toward other newly accessible jobs.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figure 3, PDF p. 20", "minutes": 4.0, "revision": "definitions-2026-10-29", "teaching_role": "result_exhibit"}, {"title": "How do the authors measure expertise in the data?", "html": "<ul><li>1977 Dictionary of Occupational Titles + 2018 O*NET task descriptions<\/li><li>Score words from school and college texts: expertise = 100 − SFI<ul><li>The <strong>Standard Frequency Index (SFI)<\/strong> combines frequency and dispersion across subject areas.<\/li><\/ul><\/li><li>Adjust with the Dale–Chall list of 3,000 words familiar to fourth graders:<br>cap the highest 10% of expertise scores among familiar words;<br>raise the lowest 10% among unfamiliar words.<\/li><li>Average adjusted word scores into tasks; task scores into occupations<br>(<a href=\"#expertise-standardization\">Comparing occupations over time<\/a>)<\/li><\/ul><table class=\"results\"><caption>Word examples: scores before adjustment<\/caption><colgroup><col style=\"width:40%\"><col style=\"width:30%\"><col style=\"width:30%\"><\/colgroup><thead><tr><th>Word<\/th><th>SFI<\/th><th>100 − SFI<\/th><\/tr><\/thead><tbody><tr><td>color<\/td><td>61.0<\/td><td>39.0<\/td><\/tr><tr><td>luminance<\/td><td>30.5<\/td><td>69.5<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 4, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 3.1 · reported SFI values; arithmetic before adjustment", "id": "s07", "teaching_role": "setup", "revision": "merged-measurement-and-word-examples-2026-10-29", "class": "expertise-measurement"}, {"id": "expertise-task-matching", "title": "First identify what work stayed, disappeared, or appeared", "html": "<p>Match tasks by <strong>meaning within an occupation<\/strong>, not identical wording.<\/p><table class=\"results\"><colgroup><col style=\"width:62%\"><col style=\"width:38%\"><\/colgroup><thead><tr><th>File-clerk example<\/th><th>Classification<\/th><\/tr><\/thead><tbody><tr><td>Sort incoming material → scan/read material to classify it<\/td><td>Retained: similar activity, new wording.<\/td><\/tr><tr><td>Operate a keypunch for tabulating cards<\/td><td>Removed: no close 2018 counterpart.<\/td><\/tr><tr><td>Input document information into computer systems<\/td><td>Added: no close 1977 counterpart.<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 3.2; Figure 8, PDF p. 33", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "expertise-centered-setup"}, {"id": "expertise-change-removal", "title": "Task removal: compare the remaining tasks with the old bundle", "html": "<p><strong>Objective:<\/strong> Did task removal increase or decrease expertise in the occupation?<\/p><div class=\"equation\">\\[\\Delta XPT^{\\mathrm{removal}}=\\overline{XPT}_{1977,\\mathrm{retained}}-\\overline{XPT}_{1977,\\mathrm{all}}\\]<\/div><table class=\"results\"><colgroup><col style=\"width:40%\"><col style=\"width:20%\"><col style=\"width:20%\"><col style=\"width:20%\"><\/colgroup><thead><tr><th>Illustrative 1977 task scores<\/th><th>All-task mean<\/th><th>Retained mean<\/th><th>Change<\/th><\/tr><\/thead><tbody><tr><td>0, 1, 2; remove task 0<\/td><td>1<\/td><td>1.5<\/td><td>+0.5<\/td><\/tr><tr><td>0, 1, 2; remove task 2<\/td><td>1<\/td><td>0.5<\/td><td>−0.5<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Removing a low-expertise task raises average expertise.<br>Removing a high-expertise task lowers it—even with the same task-count loss.<\/div>", "notes": "", "minutes": 4, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Equation (19), PDF p. 33 · illustrative calculation", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "expertise-centered-setup"}, {"id": "expertise-change-addition", "title": "Task addition: compare the new bundle with its retained tasks", "html": "<p><strong>Objective:<\/strong> Did task addition increase or decrease expertise in the occupation?<\/p><div class=\"equation\">\\[\\Delta XPT^{\\mathrm{addition}}=\\overline{XPT}_{2018,\\mathrm{all}}-\\overline{XPT}_{2018,\\mathrm{retained}}\\]<\/div><table class=\"results\"><colgroup><col style=\"width:40%\"><col style=\"width:20%\"><col style=\"width:20%\"><col style=\"width:20%\"><\/colgroup><thead><tr><th>Illustrative retained scores: 1, 2<\/th><th>New mean<\/th><th>Retained mean<\/th><th>Change<\/th><\/tr><\/thead><tbody><tr><td>Add task 3<\/td><td>2<\/td><td>1.5<\/td><td>+0.5<\/td><\/tr><tr><td>Add task 0<\/td><td>1<\/td><td>1.5<\/td><td>−0.5<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\"><strong>Net Expertise Change:<\/strong><div class=\"equation\">\\[\\Delta XPT=\\Delta XPT^{\\mathrm{removal}}+\\Delta XPT^{\\mathrm{addition}}\\]<\/div>Each comparison uses one date’s wording, excluding rewritten retained tasks.<\/div>", "notes": "", "minutes": 4, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Equation (19), PDF pp. 33–34 · illustrative calculation", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "expertise-centered-setup"}, {"id": "expertise-real-management", "title": "In the data: management support gains expertise", "html": "<div class=\"task-distribution-columns\"><figure><img src=\"figures/expertise_management_tasks.png\" alt=\"Figure 9(a). Horizontal: standardized task expertise; vertical: task counts. Purple retained, orange removed, blue added; dashed lines mark occupation means.\"><\/figure><div class=\"task-color-notes\"><p><strong>Task lists: 1977 &amp; 2018<\/strong><\/p><ul class=\"task-color-legend\"><li style=\"--task-color:#cfb0cf\"><strong>Retained:<\/strong> in both years<\/li><li style=\"--task-color:#eb6758\"><strong>Removed:<\/strong> old tasks only<\/li><li style=\"--task-color:#57a7da\"><strong>Added:<\/strong> new tasks only<\/li><\/ul><p>Horizontal: standardized expertise<br>Vertical: number of tasks<\/p><p>Occupation means:<br>dashed 1980; solid 2018<\/p><\/div><\/div><div class=\"takeaway\">Removed tasks lie mainly below the old occupational mean.<br>Added tasks extend the expert end of the bundle; both changes raise expertise.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figure 9(a), PDF p. 35", "revision": "definitions-2026-10-29", "teaching_role": "result", "class": "expertise-task-distribution"}, {"id": "expertise-real-dispatch", "title": "Dispatchers: task removal lowers expertise", "html": "<div class=\"task-distribution-columns\"><figure><img src=\"figures/expertise_dispatch_tasks.png\" alt=\"Figure 9(b). Same axes and colours. Dispatchers lose tasks toward the more expert end of their initial bundle.\"><\/figure><div class=\"task-color-notes\"><p><strong>Task lists: 1977 &amp; 2018<\/strong><\/p><ul class=\"task-color-legend\"><li style=\"--task-color:#cfb0cf\"><strong>Retained:<\/strong> in both years<\/li><li style=\"--task-color:#eb6758\"><strong>Removed:<\/strong> old tasks only<\/li><li style=\"--task-color:#57a7da\"><strong>Added:<\/strong> new tasks (none shown)<\/li><\/ul><p>Horizontal: standardized expertise<br>Vertical: number of tasks<\/p><p>Occupation means:<br>dashed 1980; solid 2018<\/p><\/div><\/div><div class=\"takeaway\">The sign depends on which tasks disappear, not simply how many.<br>For dispatchers, removal of relatively expert tasks lowers measured expertise.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Figure 9(b), PDF p. 35", "revision": "definitions-2026-10-29", "teaching_role": "result", "class": "expertise-task-distribution"}, {"id": "expertise-empirical-design", "title": "Link task changes to wages and employment", "html": "<div class=\"equation\">\\[\\Delta\\log y_o=a+\\beta\\,\\Delta XPT_o+\\gamma\\,\\Delta Tasks_o+\\delta_{g(o)}+u_o\\]<\/div><table class=\"results\"><thead><tr><th>Term<\/th><th>What is measured<\/th><\/tr><\/thead><tbody><tr><td>yₒ<\/td><td>Occupational wage or employment<\/td><\/tr><tr><td>ΔXPTₒ<\/td><td>Net expertise change, in 1980 standard deviations<\/td><\/tr><tr><td>ΔTasksₒ<\/td><td><a href=\"#expertise-task-count\" title=\"Definition and illustrative denominators\">Added share − removed share<\/a><\/td><\/tr><\/tbody><\/table><p class=\"table-note\">o: occupation; β, γ: coefficients; δ: broad occupation-group effects; a: intercept; u: residual. All changes are per decade.<\/p><div class=\"takeaway\">Within broad occupation groups, separate expertise changes from changes in task quantity.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Tables 4A and 5A, col. 5", "minutes": 3, "teaching_role": "setup", "revision": "definitions-2026-10-29", "class": "expertise-setup"}, {"title": "Expertise change and wage change", "html": "<figure><img style=\"max-height:340px\" src=\"figures/expertise_wages.png\" alt=\"Figure 10: decadalized occupational wage change versus expertise change (left) and task-quantity change (right).\"><figcaption>Figure 10: decadalized occupational wage change versus expertise change (left) and task-quantity change (right).<\/figcaption><\/figure><div class=\"takeaway\">Wages rise with expertise + task quantity, holding each other and occupation group fixed.<\/div>", "notes": "", "minutes": 3.5, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025), Expertise<\/a> · Figure 10, PDF p. 38", "id": "s08", "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "expertise-regressions", "title": "Expertise and task quantity have different employment implications", "html": "<table class=\"results\"><thead><tr><th>Explanatory variable<\/th><th>Δ log wage<\/th><th>Δ log employment<\/th><\/tr><\/thead><tbody><tr><td>Net expertise change<\/td><td>0.175 (0.047)<\/td><td>−0.510 (0.199)<\/td><\/tr><tr><td>Net task change<\/td><td>0.334 (0.123)<\/td><td>1.430 (0.523)<\/td><\/tr><tr><td>Occupations<\/td><td>303<\/td><td>303<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Tables 4A/5A, col. 5. Per-decade changes, 1980–2018; broad occupation effects; 1980 employment weights. SEs in parentheses.<\/p><div class=\"takeaway\">More expertise predicts higher wages but lower employment.<br>More tasks predict higher wages and higher employment.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Table 4A col. 5, PDF p. 39; Table 5A col. 5, PDF p. 44", "minutes": 5.5, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "expertise-magnitudes", "title": "How large are the occupation-level associations?", "html": "<table class=\"results\"><thead><tr><th>Conditional change<\/th><th>Predicted wage change<\/th><th>Predicted employment change<\/th><\/tr><\/thead><tbody><tr><td>+0.1 SD in expertise<\/td><td>+1.75 log points<\/td><td>−5.10 log points<\/td><\/tr><tr><td>+10% in the task set<\/td><td>+3.34 log points<\/td><td>+14.30 log points<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Multiply each published coefficient by 0.1. Changes are per decade; the other regressor is held fixed.<\/p><div class=\"takeaway takeaway-lines\"><div>Expertise and task quantity both predict wages.<\/div><div>Their employment associations point in opposite directions.<\/div><\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Tables 4A/5A, col. 5 · Course calculation", "minutes": 3, "teaching_role": "result_interpretation", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "expertise-removal", "title": "Removing tasks does not have a single wage implication", "html": "<table class=\"results\"><thead><tr><th>Change in the occupation<\/th><th>Coefficient in wage regression<\/th><\/tr><\/thead><tbody><tr><td>Expertise change due to task removal<\/td><td>0.147 (0.051)<\/td><\/tr><tr><td>Expertise change due to task addition<\/td><td>0.255 (0.088)<\/td><\/tr><tr><td>Share of tasks removed<\/td><td>−0.230 (0.141)<\/td><\/tr><tr><td>Share of tasks added<\/td><td>0.549 (0.206)<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Table 4B, col. 5; 303 occupations. Conditional associations; standard errors in parentheses.<\/p><div class=\"takeaway\">Losing expert tasks and losing supporting tasks have different implications.<br>Task counts alone cannot describe what remains valuable.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Table 4B col. 5, PDF p. 39", "minutes": 5.0, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "paper-productivity", "title": "Generative AI at Work", "html": "<div class=\"paper-identity-layout\"><figure><img src=\"figures/paper_productivity.png\" alt=\"Published article · First page: Generative AI at Work\"><figcaption>Published article · First page<\/figcaption><\/figure><div class=\"paper-details\"><p>Erik Brynjolfsson, Danielle Li, and Lindsey Raymond<\/p><p><strong>The Quarterly Journal of Economics · 2025<\/strong><\/p><p class=\"small\"><a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a><\/p><\/div><\/div>", "notes": "", "minutes": 0, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a> · The Quarterly Journal of Economics · 2025", "class": "paper-identity content-centered", "teaching_role": "paper_identity"}, {"title": "Can AI spread the practices of successful support agents?", "html": "<p><strong>Setting:<\/strong> a customer-support call center using live chats.<br><strong>Design:<\/strong> nonrandom staggered rollout, following a small randomized pilot.<\/p><ul><li>5,172 customer-support agents; about three million chats<\/li><li>An assistant suggests responses + links to technical documentation<\/li><li>Access begins at different dates across workers<\/li><\/ul><div class=\"takeaway\">Compare performance before and after access with workers who do not yet have access.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a>", "id": "s10", "revision": "patent-revision-2026-10-29", "teaching_role": "setup", "class": "content-centered"}, {"id": "productivity-data", "title": "What the researchers observe in the support center", "html": "<table class=\"results\"><thead><tr><th>Data<\/th><th>What it lets them measure<\/th><\/tr><\/thead><tbody><tr><td>Chat text, timestamps &amp; outcomes<\/td><td>Measure individual support interactions<\/td><\/tr><tr><td>Worker, team, location &amp; tenure<\/td><td>Track the same agents over time<\/td><\/tr><tr><td>AI access dates &amp; system interruptions<\/td><td>Compare access periods and outages<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">The productivity measures come from work records.<br>They are distinct from reported time savings.<\/div><ul><li><strong>Resolutions per hour:<\/strong> issues resolved / hours worked<\/li><li><strong>Speed:<\/strong> average time per chat<\/li><li><strong>Throughput:<\/strong> chats handled per hour<\/li><li><strong>Quality:<\/strong> issue resolution rate + customer satisfaction<\/li><\/ul>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Sections III–IV", "minutes": 5, "teaching_role": "setup", "revision": "data-and-outcomes-merged-2026-10-29", "class": "expertise-setup content-centered"}, {"title": "Difference in differences", "html": "<div class=\"equation\">\\[\\widehat\\beta=(\\overline y_{T,after}-\\overline y_{T,before})-(\\overline y_{C,after}-\\overline y_{C,before})\\]<\/div><p>Use the comparison group’s change to account for what would have happened to the treated group without the intervention.<\/p><p class=\"takeaway\">Key assumption: parallel counterfactual changes.<br>Initial productivity levels may differ.<\/p>", "notes": "", "minutes": 3, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s13", "teaching_role": "setup", "class": "content-centered"}, {"title": "Implementing the comparison with repeated observations", "html": "<div class=\"equation\">\\[y_{jt}=a_j+\\lambda_t+\\beta\\,AI_{jt}+g(\\mathrm{tenure}_{jt})+u_{jt}\\]<\/div><table><thead><tr><th>Term<\/th><th>Role<\/th><\/tr><\/thead><tbody><tr><td>Worker effect: aⱼ<\/td><td>Stable differences across workers<\/td><\/tr><tr><td>Calendar-time effect: λₜ<\/td><td>Common changes at a given date<\/td><\/tr><tr><td>Tenure controls<\/td><td>Experience accumulated on the job<\/td><\/tr><tr><td>AIⱼₜ<\/td><td>Whether the worker has access<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a>", "id": "s15", "teaching_role": "setup", "class": "content-centered"}, {"title": "Productivity rises when AI access begins", "html": "<figure><img style=\"max-height:335px\" src=\"figures/productivity_event.png\" alt=\"Figure II. Event time is measured relative to AI access; bars are 95% confidence intervals.\"><figcaption>Figure II. Event time is measured relative to AI access; bars are 95% confidence intervals.<\/figcaption><\/figure><div class=\"takeaway\">The gain begins at access and persists.<br>No comparable jump appears before treatment.<\/div>", "notes": "", "minutes": 3.0, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a> · Figure II, PDF p. 20", "id": "s16", "revision": "results-focus-2026-10-26", "teaching_role": "result_exhibit", "class": "content-centered"}, {"title": "The productivity estimate remains positive with richer controls", "html": "<table class=\"results\"><thead><tr><th>Outcome: resolutions per hour<\/th><th>(1)<\/th><th>(2)<\/th><th>(3)<\/th><\/tr><\/thead><tbody><tr><td>AI access<\/td><td>0.469<\/td><td>0.371<\/td><td>0.301<\/td><\/tr><tr><td>Standard error<\/td><td>(0.0325)<\/td><td>(0.0318)<\/td><td>(0.0329)<\/td><\/tr><tr><td>Worker effects<\/td><td>No<\/td><td>Yes<\/td><td>Yes<\/td><\/tr><tr><td>Worker-tenure effects<\/td><td>No<\/td><td>No<\/td><td>Yes<\/td><\/tr><tr><td>Agent–month observations<\/td><td>13,192<\/td><td>12,295<\/td><td>12,295<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Calendar-month and location controls throughout. Standard errors clustered by agent. Table II.<\/p><div class=\"takeaway\">The preferred estimate is 0.301 additional resolutions per hour: about 15.2% of the treated workers’ pre-access mean of 1.97.<\/div>", "notes": "", "minutes": 5.0, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Table II, PDF p. 19", "id": "s17", "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "productivity-quality", "title": "Higher throughput, with no detectable average quality loss", "html": "<table class=\"results\"><thead><tr><th>Outcome<\/th><th>Estimated effect<\/th><th>Standard error<\/th><\/tr><\/thead><tbody><tr><td>Chat duration, minutes<\/td><td>−3.746<\/td><td>0.369<\/td><\/tr><tr><td>Chats handled per hour<\/td><td>+0.365<\/td><td>0.0345<\/td><\/tr><tr><td>Resolution probability, percentage points<\/td><td>+1.32<\/td><td>0.882<\/td><\/tr><tr><td>Net promoter score, points<\/td><td>−0.119<\/td><td>0.524<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Preferred controls as before; agent-clustered errors. Resolution coefficient and error multiplied by 100. Table III.<\/p><div class=\"takeaway takeaway-lines\"><div>Agents finish chats faster and handle more of them.<\/div><div>Resolution and satisfaction estimates show no statistically clear average change.<\/div><\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Table III, PDF p. 21", "minutes": 5.0, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"title": "The gains differ with expertise: highest for the lowest-skilled workers", "html": "<figure><img style=\"max-height:340px\" src=\"figures/productivity_skill.png\" alt=\"Figure III(a): change in resolutions/hour by prior performance quintile, controlling for tenure.\"><figcaption>Figure III(a): change in resolutions/hour by prior performance quintile, controlling for tenure.<\/figcaption><\/figure><div class=\"takeaway\">The lowest-performance quintile gains about 0.5 resolutions/hour, or 36%.<br>The highest quintile has no statistically clear productivity gain.<\/div>", "notes": "", "minutes": 4.0, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a> · Figure III(a), PDF p. 24", "id": "s18", "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "productivity-quality-heterogeneity", "title": "The best initial performers can lose quality", "html": "<figure><img style=\"max-height:340px\" src=\"figures/productivity_quality_skill.png\" alt=\"Figure III, panels D–E: resolution rate and customer satisfaction by initial performance quintile.\"><figcaption>Figure III, panels D–E: resolution rate and customer satisfaction by initial performance quintile.<\/figcaption><\/figure><div class=\"takeaway\">Lower-performing agents improve quality; top performers show small declines.<br>A common assistant can spread good practice while diluting exceptional practice.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Figure III panels D–E, PDF p. 24", "minutes": 3.5, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "productivity-experience", "title": "AI assistance shortens the initial learning curve", "html": "<figure><img style=\"max-height:340px\" src=\"figures/productivity_experience.png\" alt=\"Figure V: resolutions/hour by tenure for never-treated, always-treated, and month-five adopters.\"><figcaption>Figure V: resolutions/hour by tenure for never-treated, always-treated, and month-five adopters.<\/figcaption><\/figure><div class=\"takeaway\">Workers with access reach about 2.5 resolutions/hour after two months; unaided workers take roughly eight to ten months to reach that level.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Figure V, PDF p. 27", "minutes": 3.5, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"title": "Some improvements persist when assistance is unavailable", "html": "<figure><img style=\"max-height:330px\" src=\"figures/productivity_outages.png\" alt=\"Figure VII, panels A–B: chat duration outside outages (left) and during major outages (right).\"><figcaption>Figure VII, panels A–B: chat duration outside outages (left) and during major outages (right).<\/figcaption><\/figure><div class=\"takeaway\">Previously exposed agents still handle chats faster during outages, especially after longer exposure.<br>This is evidence consistent with learning.<\/div>", "notes": "", "minutes": 3.5, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Figure VII panels A–B, PDF p. 34", "id": "s19", "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "productivity-work-experience", "title": "The interaction with customers also improves", "html": "<table class=\"results\"><thead><tr><th>Outcome<\/th><th>AI access effect<\/th><th>Standard error<\/th><\/tr><\/thead><tbody><tr><td>Customer sentiment (−1 to +1 scale)<\/td><td>+0.177<\/td><td>0.0116<\/td><\/tr><tr><td>Agent sentiment (same scale)<\/td><td>+0.0198<\/td><td>0.00599<\/td><\/tr><tr><td>Requests for a manager, percentage points<\/td><td>−0.875<\/td><td>0.201<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Table IV; preferred controls and agent-clustered errors. Manager-request coefficient and error multiplied by 100.<\/p><div class=\"takeaway\">Customers’ messages become more positive and escalations decline.<br>The gain includes a less difficult interaction, as well as faster work.<\/div>", "notes": "", "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025)<\/a> · Table IV, PDF p. 43", "minutes": 3.5, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"title": "Assistance and learning in customer support", "html": "<ul><li>About 15% more resolved issues per hour<\/li><li>Larger gains for novices &amp; initially low-performing agents<\/li><li>Faster learning curve + persistent gains during outages<\/li><li>Quality declines for some top performers despite the average gain<\/li><\/ul><div class=\"takeaway\">Some useful practice carries over without the assistant.<br>Does that also happen in work requiring years of professional training?<\/div>", "notes": "", "minutes": 2.5, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a>", "id": "s20", "revision": "patent-revision-2026-10-29", "teaching_role": "result_interpretation", "class": "content-centered"}, {"id": "paper-patent", "title": "Does AI assistance enhance or erode expertise?", "html": "<div class=\"paper-identity-layout\"><figure><img src=\"figures/paper_patent.png\" alt=\"NBER Working Paper 35720 title page\"><figcaption>NBER Working Paper 35720 · September 2026<\/figcaption><\/figure><div class=\"paper-details\"><p>David Autor, Tanya Rodchenko, Josh Martin,<br>Zanna Iscenko, Scott Strand,<br>David Pearl &amp; Melissa Ferere<\/p><p><strong>A three-month experiment with practicing patent lawyers<\/strong><\/p><p><a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a> · <a href=\"https://research.google/blog/does-better-work-always-mean-better-workers/\" target=\"_blank\" rel=\"noopener\">Google Research summary<\/a><\/p><\/div><\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a>", "minutes": 1, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "paper-identity content-centered"}, {"id": "patent-question", "title": "Better drafting and better judgment are separate outcomes", "html": "<table class=\"results\"><thead><tr><th>With an assistant<\/th><th>Without an assistant<\/th><\/tr><\/thead><tbody><tr><td>Draft a patent from invention materials<\/td><td>Find and correct flaws in an existing draft<\/td><\/tr><tr><td>Produce a stronger document today<\/td><td>Use professional judgment after three months<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">An assistant can improve our work without developing our independent judgment.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a>", "minutes": 3, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "expertise-setup content-centered"}, {"id": "patent-randomization", "title": "Random assignment within participating law firms", "html": "<ul><li>133 practicing patent lawyers at 11 U.S. law firms<\/li><li>90 assigned AI access; 43 assigned to the control group<\/li><li>Randomize within firm, stratifying by legal experience<\/li><li>Both groups offered AI basics; treated lawyers also receive tool training<\/li><\/ul><div class=\"takeaway\">Treatment is access to the assistant + its training.<br>The comparison estimates the effect of assignment to that package.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Sections 3.1–3.2; Table 1", "minutes": 4, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-assistant", "title": "What the AI assistant does", "html": "<ul><li>Draft or rewrite selected text using a prompt<\/li><li>Insert text using the surrounding document as context<\/li><li>Give feedback as an editor, expert or intended audience<\/li><li>Identify inconsistencies against a set of review criteria<\/li><\/ul><div class=\"takeaway\">The lawyer supplies the invention + drafting goals.<br>The lawyer also decides what to accept, change or reject.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Section 3.2", "minutes": 3, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-timeline", "title": "Three assessments: drafting and independent review", "html": "<table class=\"results\"><thead><tr><th>When<\/th><th>Task<\/th><th>AI during the test?<\/th><th>Completed<\/th><\/tr><\/thead><tbody><tr><td>Day 10<\/td><td>Draft dependent claims + description<\/td><td>Treated only<\/td><td>105 lawyers<\/td><\/tr><tr><td>Day 90<\/td><td>Draft a different, harder patent<\/td><td>Treated only<\/td><td>98 lawyers<\/td><\/tr><tr><td>Day 90<\/td><td>Redline a flawed patent draft<\/td><td>Neither group<\/td><td>91 lawyers<\/td><\/tr><\/tbody><\/table>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Section 3.2; Table 1", "minutes": 4, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "expertise-setup content-centered"}, {"id": "patent-scoring", "title": "Blinded experts evaluate five dimensions of quality", "html": "<table class=\"results\"><thead><tr><th>Dimension<\/th><th>What a stronger patent does<\/th><\/tr><\/thead><tbody><tr><td>Enforceability<\/td><td>Avoid wording that weakens legal protection<\/td><\/tr><tr><td>Technical accuracy<\/td><td>Describe the invention correctly<\/td><\/tr><tr><td>Strategic ambiguity<\/td><td>Keep useful breadth without creating confusion<\/td><\/tr><tr><td>Completeness &amp; alignment<\/td><td>Include the elements needed to support the claims<\/td><\/tr><tr><td>Clarity<\/td><td>Communicate the invention and claims clearly<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Two independent patent-lawyer raters; 1–5 rubric scores; treatment status hidden.<\/p>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Section 3.3; Appendix A2.4", "minutes": 4, "teaching_role": "setup", "revision": "patent-revision-2026-10-29", "class": "expertise-setup content-centered"}, {"id": "patent-estimation", "title": "The regression compares assigned groups within firms", "html": "<div class=\"equation patent-regression\">\\[z_{irk}=a+\\overset{\\substack{\\text{Coefficient of Interest}\\\\\\downarrow}}{\\mathbf{\\tau}}T_i+\\underbrace{\\lambda_{f(i)}+\\delta_k}_{\\text{Firm + Quality effects}}+u_{irk}\\]<\/div><table class=\"results\"><thead><tr><th>Outcome: standardized drafting quality<\/th><th>Day 10<\/th><th>Day 90<\/th><\/tr><\/thead><tbody><tr><td>Assigned AI access<\/td><td>0.34 (0.16)<\/td><td>0.38 (0.15)<\/td><\/tr><tr><td>Lawyers completing the task<\/td><td>105<\/td><td>98<\/td><\/tr><tr><td>Rating × dimension observations<\/td><td>1,050<\/td><td>995<\/td><\/tr><tr><td>Firm + quality-dimension effects<\/td><td>Yes<\/td><td>Yes<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Human expert ratings. Standard errors clustered by lawyer, in parentheses. Tables 3–4, col. 2.<\/p>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Section 3.4; Tables 3–4, col. 2 · PDF pp. 21–22", "minutes": 8, "teaching_role": "result_exhibit", "revision": "regression-and-drafting-results-2026-10-29", "class": "expertise-setup content-centered"}, {"id": "patent-drafting-dimensions", "title": "Drafting gains extend beyond clearer prose", "html": "<figure><img src=\"figures/patent_drafting_quality.png\" alt=\"Figure 1, drafting panels · Black: all; blue: junior; orange: senior. Bars show 95% confidence intervals.\"><figcaption>Figure 1, drafting panels · Black: all; blue: junior; orange: senior. Bars show 95% confidence intervals.<\/figcaption><\/figure><div class=\"takeaway\">Point estimates improve across all five dimensions.<br>Junior lawyers have larger estimated gains in both drafting tests.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Figure 1, first two panels · PDF p. 20 · <a href=\"#patent-drafting-distribution\">Score distributions<\/a>", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-time", "title": "Junior lawyers also save time on the first drafting task; Seniors do not!", "html": "<table class=\"results\"><thead><tr><th>Effect on minutes spent<\/th><th>Day 10<\/th><th>Day 90<\/th><\/tr><\/thead><tbody><tr><td>All lawyers<\/td><td>−9.97 (5.11)<\/td><td>−9.61 (8.65)<\/td><\/tr><tr><td>Junior lawyers<\/td><td>−17.91 (9.13)<\/td><td>−21.63 (18.24)<\/td><\/tr><tr><td>Senior lawyers<\/td><td>−4.91 (5.22)<\/td><td>−4.54 (9.59)<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Table 8, cols. 1–4. Self-reported timed work; robust SEs. N = 102 and 96.<\/p><div class=\"takeaway\">Early time savings are concentrated among juniors.<br>The day-90 estimates are too imprecise to establish time savings.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Table 8, cols. 1–4 · PDF p. 35", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-redlining-table", "title": "The unaided judgment gain is concentrated among seniors", "html": "<table class=\"results\"><thead><tr><th>Effect on day-90 redlining quality<\/th><th>All lawyers<\/th><th>Junior<\/th><th>Senior<\/th><\/tr><\/thead><tbody><tr><td>Earlier assignment to AI access<\/td><td>0.32 (0.15)<\/td><td>−0.03 (0.20)<\/td><td>0.45 (0.19)<\/td><\/tr><tr><td>Experience group<\/td><td>All<\/td><td>Under 7 years<\/td><td>7+ years<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Table 6, cols. 2 and 4. No AI permitted for either group. 91 lawyers; 925 rating × dimension observations.<\/p><div class=\"takeaway\">Seniors given earlier access perform better without AI.<br>For juniors, the estimate is close to zero and imprecise.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Table 6, cols. 2 and 4 · PDF p. 26 · <a href=\"#patent-original-regression\">Full regression table<\/a>", "minutes": 5, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-experience-results", "title": "Who benefits depends on which outcome we measure", "html": "<figure><img src=\"figures/patent_experience_comparison.svg\" alt=\"Published human-rating coefficients; course plot. Intervals: estimate ± 1.96 × rounded SE.\"><figcaption>Published human-rating coefficients; course plot. Intervals: estimate ± 1.96 × rounded SE.<\/figcaption><\/figure><div class=\"takeaway\">Juniors’ larger drafting gains do not carry over to the unaided test.<br>Seniors show the reverse pattern: a clear gain in independent judgment.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Tables 3, 4 and 6, col. 4 · <a href=\"data/patent_results.csv\" download>Exhibit coefficients<\/a>", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-redlining-dimensions", "title": "Senior gains span the dimensions of judgment", "html": "<figure><img src=\"figures/patent_redlining_quality.png\" alt=\"Figure 1, redlining panel · All participants instructed to work without AI.\"><figcaption>Figure 1, redlining panel · All participants instructed to work without AI.<\/figcaption><\/figure><div class=\"takeaway\">Senior estimates are positive across all five dimensions.<br>Junior estimates are small or uncertain, with some below zero.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Figure 1, third panel · PDF p. 20", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-distributions", "title": "The junior average hides a wider spread of scores", "html": "<figure><img src=\"figures/patent_redlining_distribution.png\" alt=\"Figure 3 · Blue: control; orange: earlier AI access. Firm-adjusted average ratings, 1–5 scale.\"><figcaption>Figure 3 · Blue: control; orange: earlier AI access. Firm-adjusted average ratings, 1–5 scale.<br><a href=\"#patent-distribution-table\">Probability changes by score fifth: juniors vs seniors (appendix)<\/a><\/figcaption><\/figure><div class=\"takeaway\">Junior scores spread toward both poor and good performance.<br>Senior scores shift toward stronger performance overall.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Figure 3 · PDF p. 27", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"id": "patent-scope", "title": "How far can we take the learning result?", "html": "<ul><li>Three months of access; one unaided patent-review exercise<\/li><li>Completion falls from 133 assigned lawyers to 91 redlining submissions<\/li><li>No-AI instructions were clear; individual compliance could not be monitored<\/li><li>Excluding suspected AI use preserves the pattern but reduces precision<\/li><\/ul><div class=\"takeaway\">Evidence for improved unaided judgment among seniors.<br>No average junior gain is not proof of permanent skill loss.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Sections 3.2, 4.4 and 6 · <a href=\"#patent-robustness\">Sensitivity check<\/a> · <a href=\"#patent-real-work\">Ordinary client work<\/a>", "minutes": 3, "teaching_role": "result_interpretation", "revision": "patent-revision-2026-10-29", "class": "content-centered"}, {"title": "AI changes output, expertise and the value of work", "html": "<table class=\"results\"><thead><tr><th>Paper<\/th><th>What its results establish<\/th><\/tr><\/thead><tbody><tr><td>Expertise<\/td><td>The tasks left in a job matter for wages and entry<\/td><\/tr><tr><td>Generative AI at Work<\/td><td>Assistance raises output most for novices and low performers<\/td><\/tr><tr><td>Patent-lawyer experiment<\/td><td>Better assisted drafting need not produce better unaided judgment<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Who gains depends on the task, the worker and the outcome.<br>Current productivity gains alone do not tell us how expertise develops.<\/div>", "notes": "", "minutes": 3, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s26", "revision": "patent-revision-2026-10-29", "teaching_role": "synthesis", "class": "expertise-closing"}, {"title": "Appendix: Employment and wages can move in opposite directions", "html": "<table><thead><tr><th>Change in remaining expertise<\/th><th>Entry and allocation mechanism<\/th><th>Possible wage implication<\/th><\/tr><\/thead><tbody><tr><td>Lower requirement<\/td><td>More workers qualify for the remaining job<\/td><td>Lower scarcity value for incumbents<\/td><\/tr><tr><td>Greater importance of expert work<\/td><td>Production relies more on scarce expertise<\/td><td>Higher reward to that expertise<\/td><\/tr><\/tbody><\/table><p>Task quantities and product demand also affect employment.<\/p>", "notes": "", "minutes": 2.0, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025), Expertise<\/a>", "id": "s06", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"title": "Appendix: From a mechanism to a workplace", "html": "<p>Can AI transmit useful expertise to workers who initially have less of it?<\/p><ul><li>Observed access to a specific tool<\/li><li>Consistent outcomes before + after access<\/li><li>Credible comparison without access<\/li><\/ul>", "notes": "", "minutes": 2.0, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s09", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"title": "Appendix: Why a before-and-after comparison is incomplete", "html": "<p>Productivity could rise even without AI access.<\/p><ul><li>Worker experience<\/li><li>Customer problem mix<\/li><li>Management, staffing &amp; demand<\/li><\/ul><p>Workers who receive access may also differ from those who never receive it.<\/p>", "notes": "", "minutes": 2.0, "source": "<a href=\"https://doi.org/10.1093/qje/qjae044\" target=\"_blank\" rel=\"noopener\">Brynjolfsson, Li and Raymond (2025), Generative AI at Work<\/a>", "id": "s12", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"title": "Appendix: An illustrative difference-in-differences calculation", "html": "<div class=\"widget\" data-widget=\"did\"><\/div>", "notes": "", "minutes": 4.5, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s14", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"title": "Appendix: What a “20% productivity gain” would and would not establish", "html": "<table class=\"results\"><thead><tr><th>Required evidence<\/th><th>Conclusion it supports<\/th><\/tr><\/thead><tbody><tr><td>Output with quality held accountable<\/td><td>A gain in useful production, not merely faster responses.<\/td><\/tr><tr><td>A credible untreated comparison<\/td><td>An effect attributable to access in the studied setting.<\/td><\/tr><tr><td>Effects across workers and tasks<\/td><td>Who benefits, who does not, and where training helps.<\/td><\/tr><tr><td>Prices, demand, entry, and pay<\/td><td>Whether productivity gains become jobs or higher wages.<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 4.0, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s27", "revision": "results-2026-10-25", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"id": "patent-drafting-distribution", "title": "Appendix: Drafting score distributions", "html": "<figure><img src=\"figures/patent_drafting_distribution.png\" alt=\"Figure 2 · Blue: control; orange: AI access. Each column is a different experience group.\"><figcaption>Figure 2 · Blue: control; orange: AI access. Each column is a different experience group.<\/figcaption><\/figure><div class=\"takeaway\">The distribution generally moves away from poor drafting scores.<br>The amount and precision of this shift differ by task and group.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Figure 2; Table 5 · PDF pp. 23–24 · <a href=\"#patent-drafting-dimensions\">Return<\/a>", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "appendix": true, "class": "content-centered"}, {"id": "patent-original-regression", "title": "Appendix: The original redlining regression table", "html": "<figure><img src=\"figures/patent_table6_original.png\" alt=\"Table 6 · Human expert ratings in cols. 1–4; LLM and combined ratings in cols. 5–8.\"><figcaption>Table 6 · Human expert ratings in cols. 1–4; LLM and combined ratings in cols. 5–8.<\/figcaption><\/figure><div class=\"takeaway\">The lecture uses human ratings: pooled effect in col. 2 and experience-specific effects in col. 4.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Table 6 · PDF p. 26 · <a href=\"#patent-redlining-table\">Return to results<\/a>", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "appendix": true, "class": "content-centered"}, {"id": "patent-robustness", "title": "Appendix: Excluding suspected AI use reduces precision", "html": "<table class=\"results\"><thead><tr><th>Unaided redlining effect<\/th><th>All lawyers<\/th><th>Senior lawyers<\/th><\/tr><\/thead><tbody><tr><td>Main human-rating estimate<\/td><td>0.32 SD; p = .04<\/td><td>0.45 SD; p = .02<\/td><\/tr><tr><td>Exclude 15 flagged submissions<\/td><td>0.25 SD; p = .14<\/td><td>0.39 SD; p = .06<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">The direction survives this check; the evidence becomes less precise.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Section 4.4; Table A6 · <a href=\"#patent-scope\">Return<\/a>", "minutes": 3, "teaching_role": "optional", "revision": "patent-revision-2026-10-29", "appendix": true, "class": "content-centered"}, {"id": "patent-real-work", "title": "Appendix: Do benchmark gains show up in ordinary patent work?", "html": "<table class=\"results\"><thead><tr><th>Self-reported work outcome<\/th><th>Effect<\/th><th>Standard error<\/th><\/tr><\/thead><tbody><tr><td>Weeks to complete a patent<\/td><td>−0.76<\/td><td>0.81<\/td><\/tr><tr><td>Reviewer input, SD<\/td><td>−0.39<\/td><td>0.28<\/td><\/tr><tr><td>Edits and corrections, SD<\/td><td>−0.15<\/td><td>0.28<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Table 9, cols. 5, 7 and 9. N = 67, 66 and 66; firm effects; robust SEs.<\/p><div class=\"takeaway\">These estimates are too imprecise to establish improvements in ordinary client work.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Table 9 · PDF p. 37 · <a href=\"#patent-scope\">Return<\/a>", "minutes": 3, "teaching_role": "optional", "revision": "patent-revision-2026-10-29", "appendix": true, "class": "content-centered"}, {"id": "expertise-standardization", "title": "Appendix: Comparing occupations over time", "html": "<table class=\"results\"><colgroup><col style=\"width:32%\"><col style=\"width:68%\"><\/colgroup><thead><tr><th>Step<\/th><th>Construction<\/th><\/tr><\/thead><tbody><tr><td>Occupational title<\/td><td>Mean of its task scores.<\/td><\/tr><tr><td>303 Census occupations<\/td><td>Employment-weighted mean of the underlying titles.<\/td><\/tr><tr><td>Common scale<\/td><td>Subtract the 1980 occupation mean; divide by its standard deviation.<\/td><\/tr><\/tbody><\/table><p>A task score of <strong>+1<\/strong> is one baseline occupation standard deviation above the mean. Apply the same scaling to both dates.<\/p><div class=\"takeaway\">This lets us compare expertise across occupations and over time.<br>Vague descriptions or expertise expressed in common words can be missed.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 3.1: aggregation and standardization · <a href=\"#s07\">Back to expertise measurement<\/a>", "revision": "definitions-2026-10-29", "teaching_role": "setup", "appendix": true, "class": "content-centered"}, {"id": "expertise-task-count", "title": "Appendix: Measuring changes in task quantity", "html": "<table class=\"results\"><colgroup><col style=\"width:32%\"><col style=\"width:31%\"><col style=\"width:37%\"><\/colgroup><thead><tr><th>Quantity measure<\/th><th>Denominator<\/th><th>Illustrative example<\/th><\/tr><\/thead><tbody><tr><td>Share of tasks removed<\/td><td>All 1977 tasks<\/td><td>1 of 3 = 33.3%<\/td><\/tr><tr><td>Share of tasks added<\/td><td>All 2018 tasks<\/td><td>1 of 4 = 25.0%<\/td><\/tr><tr><td>Net task change<\/td><td>Added share − removed share<\/td><td>25.0% − 33.3% = −8.3 points<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">The regressions include expertise change and task-quantity change.<br>“Net task change” is a difference of shares, not growth in the raw task count.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://doi.org/10.1093/jeea/jvaf023\" target=\"_blank\" rel=\"noopener\">Autor and Thompson (2025)<\/a> · Section 3.2, PDF p. 34 · illustrative denominators · <a href=\"#expertise-empirical-design\">Back to the regression<\/a>", "revision": "definitions-2026-10-29", "teaching_role": "setup", "appendix": true, "class": "content-centered"}, {"id": "patent-distribution-table", "title": "Appendix: Changes in redlining scores by fifth", "html": "<table class=\"results\"><thead><tr><th>Change in probability of a score in…<\/th><th>Junior<\/th><th>Senior<\/th><\/tr><\/thead><tbody><tr><td>Highest fifth<\/td><td>+6 (4)<\/td><td>+3 (7)<\/td><\/tr><tr><td>Second-highest fifth<\/td><td>+19 (15)<\/td><td>+22 (7)<\/td><\/tr><tr><td>Middle fifth<\/td><td>−5 (10)<\/td><td>−4 (7)<\/td><\/tr><tr><td>Second-lowest fifth<\/td><td>−42 (16)<\/td><td>−8 (8)<\/td><\/tr><tr><td>Lowest fifth<\/td><td>+22 (11)<\/td><td>−14 (8)<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Percentage points; robust SEs in parentheses. Table 7. Fifths defined from the full valid sample.<\/p><div class=\"takeaway\">Junior scores leave the second-lowest fifth for both tails.<br>For seniors, the clearest increase is in the second-highest fifth.<\/div>", "notes": "", "source": "<a href=\"https://shapingwork.mit.edu/wp-content/uploads/2026/09/Autor-et-al-Sept-2026.pdf\" target=\"_blank\" rel=\"noopener\">Autor et al. (2026), patent-lawyer experiment<\/a> · Table 7 · PDF p. 27 · <a href=\"#patent-distributions\">Back to score distributions<\/a>", "minutes": 4, "teaching_role": "result_exhibit", "revision": "patent-revision-2026-10-29", "class": "content-centered", "appendix": true}], "revision_date": "2026-10-29", "revision_focus": "Student-facing definitions, worked measurement examples, and setup before model and empirical exhibits; preserve results.", "pacing": {"main_slides": 50, "appendix_slides": 12, "guidance": "Aim for roughly 70% results and interpretation / 30% question and setup in delivery. Do not omit necessary definitions to hit an exact split; slide timings remain rough preparation aids."}, "content_minutes": 173.0, "hideNotes": true};
